import type { ModelScanStage } from "@/components/ui/model-scan-primitive"

type ModelScanLabels = {
  /** The 3D model's name once it shows, unless `modelAlt` names it. */
  model: string
  /** What each stage is doing: the progress bar's label, and what screen readers hear when it starts. */
  stage: Record<Exclude<ModelScanStage, "photo" | "error">, string>
  cancel: string
  retry: string
  error: string
  progress: (percent: number) => string
}

const modelScanLabels: ModelScanLabels = {
  model: "3D model",
  stage: {
    detecting: "Finding points on the photo",
    building: "Building the 3D model",
    refining: "Refining the shape",
    ready: "The 3D model is ready",
  },
  cancel: "Cancel",
  retry: "Try again",
  error: "The 3D model could not be made",
  progress: (percent) => `${String(percent)}%`,
}

export { modelScanLabels }
export type { ModelScanLabels }

/** A point on the photo, each value a fraction of its width or height from its top left corner. */
type ModelScanPoint = { x: number; y: number }

/** Points as an engine sends them: interleaved x, y pairs, or objects. */
type ModelScanPointList = Float32Array | readonly number[] | readonly ModelScanPoint[]

/**
 * One detector's points, like the face or the body, which light up on their own. `aspect` is the width over the
 * height of the frame the points are fractions of, when that isn't the photo's: the photo is taken as drawn inside
 * it with `object-fit: contain`, centred, as detectors that pad their input to a fixed shape report.
 */
type ModelScanPointGroup = { source: string; points: ModelScanPointList; aspect?: number }

/** One list of points, or groups of them; a later group with the same `source` replaces the earlier one. */
type ModelScanPoints = ModelScanPointList | readonly ModelScanPointGroup[]

/** A group ready to draw: its points as interleaved x, y fractions of the photo. */
type ModelScanDrawnGroup = { source: string; coords: Float32Array }

const isGroupList = (points: ModelScanPoints): points is readonly ModelScanPointGroup[] =>
  Array.isArray(points) && points.length > 0 && typeof points[0] === "object" && "source" in (points[0] as object)

function interleaved(list: ModelScanPointList) {
  if (ArrayBuffer.isView(list)) return list
  if (list.length > 0 && typeof list[0] === "number") return Float32Array.from(list as readonly number[])
  const coords = new Float32Array(list.length * 2)
  ;(list as readonly ModelScanPoint[]).forEach((point, i) => {
    coords[i * 2] = point.x
    coords[i * 2 + 1] = point.y
  })
  return coords
}

/**
 * Points in fractions of the photo, grouped by source in the order the sources first arrived. Points from a frame of
 * another `aspect` are moved onto the photo; points off the photo are dropped.
 */
function pointGroups(points: ModelScanPoints | undefined, ratio: number): ModelScanDrawnGroup[] {
  if (!points || points.length === 0) return []
  const groups = isGroupList(points) ? points : [{ source: "points", points }]
  const bySource = new Map<string, ModelScanPointGroup>()
  for (const group of groups) bySource.set(group.source, group)
  return [...bySource.values()].map((group) => {
    const coords = interleaved(group.points)
    const aspect = group.aspect
    if (!aspect || Math.abs(aspect / ratio - 1) < 0.01) return { source: group.source, coords }
    // The photo's share of the frame along the axis it doesn't fill, and the band before it.
    const wide = ratio > aspect
    const share = wide ? aspect / ratio : ratio / aspect
    const offset = (1 - share) / 2
    const mapped: number[] = []
    for (let i = 0; i + 1 < coords.length; i += 2) {
      const x = wide ? (coords[i] ?? 0) : ((coords[i] ?? 0) - offset) / share
      const y = wide ? ((coords[i + 1] ?? 0) - offset) / share : (coords[i + 1] ?? 0)
      if (x < 0 || x > 1 || y < 0 || y > 1) continue
      mapped.push(x, y)
    }
    return { source: group.source, coords: Float32Array.from(mapped) }
  })
}

export { pointGroups }
export type { ModelScanDrawnGroup, ModelScanPoint, ModelScanPointGroup, ModelScanPointList, ModelScanPoints }

import { announce, css, definePrimitive, dispatch, prepareAnnouncements, type ChangeDetails } from "@ui-sdk/core"

/**
 * `photo` before anything runs, `detecting` while points light up over it, `building` while the photo turns into
 * the base model, `refining` while weights stream in, `ready` to orbit, `error` to retry.
 */
type ModelScanStage = "photo" | "detecting" | "building" | "refining" | "ready" | "error"

type ModelScanActionReason = "trigger-press" | "imperative"

type ModelScanAnnouncements = {
  stage: (stage: ModelScanStage) => string | undefined
  /** `percent` is a whole number from 0 to 100. */
  progress: (percent: number) => string
  error: string
}

type ModelScanOptions = {
  stage?: ModelScanStage
  /** From 0 to 1 within the stage; undefined while the engine can't tell. */
  progress?: number
  onCancel?: (value: null, details: ChangeDetails<ModelScanActionReason>) => void
  onRetry?: (value: null, details: ChangeDetails<ModelScanActionReason>) => void
  /** The photo's width over its height. */
  ratio?: number
  /** The model has taken the photo's place in the 3D scene. */
  introDone?: boolean
  announcements?: ModelScanAnnouncements
}

const working: readonly ModelScanStage[] = ["detecting", "building", "refining"]
const cancelable: readonly ModelScanStage[] = ["photo", ...working]

const clamp = (value: number) => Math.min(1, Math.max(0, Number.isFinite(value) ? value : 0))

// Progress is read at most every tenth, and no sooner than this after the last reading.
const progressStep = 10
const progressInterval = 2000

const modelScan = definePrimitive({
  name: "model-scan",
  options: {
    stage: "string",
    progress: "number",
    onCancel: "callback",
    onRetry: "callback",
    ratio: "number",
    introDone: "boolean",
    announcements: "value",
  },
  controlled: ["stage"],
  state: (options: ModelScanOptions) => ({
    stage: options.stage ?? "photo",
    progress: options.progress,
    ratio: options.ratio ?? 3 / 4,
    introDone: options.introDone ?? false,
  }),
  sync: (options) => ({
    stage: options.stage ?? "photo",
    progress: options.progress,
    ratio: options.ratio ?? 3 / 4,
    introDone: options.introDone ?? false,
  }),
  api: (context) => {
    const { store } = context
    // A call that can't apply throws, so an agent's step fails with why instead of reporting success.
    const run = (name: "onCancel" | "onRetry", allowed: readonly ModelScanStage[], event?: Event) => {
      const current = store.get().stage
      const action = name.slice(2)
      if (!allowed.includes(current)) {
        throw new Error(`${action} works only in ${allowed.join(", ")} (stage: ${current}).`)
      }
      if (!context.options()[name]) throw new Error(`${action} isn't offered: there is no ${name}.`)
      return !dispatch(context, name, null, { reason: event ? "trigger-press" : "imperative", event })
    }
    return {
      /** Stops the run at any stage before it's ready, through `onCancel`. */
      cancel: (event?: Event) => run("onCancel", cancelable, event),
      /** Starts again after an error, through `onRetry`. */
      retry: (event?: Event) => run("onRetry", ["error"], event),
      canCancel: () => cancelable.includes(store.get().stage) && Boolean(context.options().onCancel),
      announcements: () => context.options().announcements,
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-stage": state.stage,
        "data-intro": state.introDone ? "done" : undefined,
        "aria-busy": working.includes(state.stage) ? "true" : undefined,
        style: css({
          "--model-scan-ratio": String(state.ratio),
          "--model-scan-progress": state.progress === undefined ? undefined : String(clamp(state.progress)),
        }),
      }),
      bind: (el, part) => {
        const doc = el.ownerDocument
        prepareAnnouncements(doc)
        let { stage } = part.store.get()
        let lastStep = -1
        let lastTime = -Infinity
        return part.store.subscribe(() => {
          const state = part.store.get()
          const messages = part.api.announcements()
          if (state.stage !== stage) {
            stage = state.stage
            lastStep = -1
            lastTime = -Infinity
            if (!messages) return
            if (stage === "error") announce(messages.error, { doc, priority: "assertive" })
            else {
              const text = messages.stage(stage)
              if (text) announce(text, { doc })
            }
            return
          }
          if (!working.includes(state.stage) || state.progress === undefined || !messages) return
          const percent = Math.round(clamp(state.progress) * 100)
          const step = Math.floor(percent / progressStep)
          const now = Date.now()
          if (step === lastStep || (now - lastTime < progressInterval && percent < 100)) return
          lastStep = step
          lastTime = now
          announce(messages.progress(percent), { doc })
        })
      },
    }),
    // Once the 3D scene shows the photo exactly where the 2D one is, the 2D layer goes.
    photo: slot<{ handedOff?: boolean }>({
      props: { handedOff: "boolean" },
      attrs: (state, part) => ({
        "data-stage": state.stage,
        "data-handed-off": part.props.handedOff ? "" : undefined,
      }),
    }),
    effect: slot({
      present: (state) => state.stage === "detecting",
      attrs: (state) => ({
        "aria-hidden": "true",
        "data-determinate": state.progress === undefined ? undefined : "",
      }),
    }),
    points: slot<{ handedOff?: boolean }>({
      props: { handedOff: "boolean" },
      present: (state, part) => state.stage === "detecting" || (state.stage === "building" && !part.props.handedOff),
      attrs: () => ({ "aria-hidden": "true" }),
    }),
  }),
  agent: { actions: ["cancel", "retry"] },
})

export { modelScan }
export type { ModelScanActionReason, ModelScanAnnouncements, ModelScanOptions, ModelScanStage }

import {
  BufferAttribute,
  BufferGeometry,
  Color,
  Mesh,
  PlaneGeometry,
  Points,
  ShaderMaterial,
  type Texture,
  type Vector3,
} from "three"

// The same noise decides where the photo burns away and when each particle leaves it, so particles fly off from
// the burning edge. Value noise over a hash, cheap enough per vertex and per fragment.
const noise = /* glsl */ `
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float burn(vec2 uv) { return valueNoise(uv * 9.0) * 0.75 + hash(floor(uv * 140.0)) * 0.25; }
float edgeOf(float progress) { return progress * 1.3 - 0.15; }
`

const planeVertex = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`

const planeFragment = /* glsl */ `
uniform sampler2D map;
uniform float progress;
uniform float opacity;
uniform vec3 edgeColor;
varying vec2 vUv;
${noise}
void main() {
  vec4 color = texture2D(map, vUv);
  float n = burn(vUv);
  float edge = edgeOf(progress);
  if (progress > 0.0 && n < edge) discard;
  float glow = progress > 0.0 ? smoothstep(edge + 0.06, edge, n) : 0.0;
  gl_FragColor = vec4(mix(color.rgb, edgeColor, glow), color.a * opacity);
  #include <colorspace_fragment>
}
`

const particleVertex = /* glsl */ `
attribute vec2 spot;
attribute vec3 drift;
uniform sampler2D map;
uniform float progress;
uniform vec2 size;
uniform float pointSize;
uniform vec3 edgeColor;
varying vec4 vColor;
${noise}
void main() {
  float age = (edgeOf(progress) - burn(spot)) / 0.45;
  if (age <= 0.0 || age >= 1.0) {
    gl_Position = vec4(2.0, 2.0, 2.0, 1.0);
    gl_PointSize = 0.0;
    vColor = vec4(0.0);
    return;
  }
  vec3 local = vec3((spot - 0.5) * size, 0.0) + drift * age + vec3(0.0, age * age * size.y * 0.12, 0.0);
  vec4 view = modelViewMatrix * vec4(local, 1.0);
  gl_Position = projectionMatrix * view;
  gl_PointSize = pointSize * (1.0 - age * 0.6) / -view.z;
  vec3 color = mix(texture2D(map, spot).rgb, edgeColor, smoothstep(0.35, 0.0, age) * 0.6);
  vColor = vec4(color, (1.0 - age) * 0.8 * texture2D(map, spot).a);
}
`

const particleFragment = /* glsl */ `
varying vec4 vColor;
void main() {
  if (length(gl_PointCoord - 0.5) > 0.5) discard;
  gl_FragColor = vColor;
  #include <colorspace_fragment>
}
`

/** Columns of particles across the photo; rows follow its ratio. */
const particleColumns = 72

/**
 * The photo on a plane, and particles on a grid over it. Set `progress` from 0 (the photo, whole) to 1 (burned
 * away, its particles gone) and `opacity` for a plain fade. Sizes are set per frame by `place`.
 */
function createDissolve(texture: Texture, ratio: number, edge: Color) {
  const uniforms = {
    map: { value: texture },
    progress: { value: 0 },
    opacity: { value: 1 },
    edgeColor: { value: edge },
    size: { value: [1, 1] },
    pointSize: { value: 1 },
  }
  const plane = new Mesh(
    new PlaneGeometry(1, 1),
    new ShaderMaterial({
      uniforms,
      vertexShader: planeVertex,
      fragmentShader: planeFragment,
      transparent: true,
    }),
  )
  plane.renderOrder = 1

  const rows = Math.max(1, Math.round(particleColumns / ratio))
  const count = particleColumns * rows
  const spots = new Float32Array(count * 2)
  const drifts = new Float32Array(count * 3)
  let seed = 7
  const random = () => {
    seed = (seed * 16_807) % 2_147_483_647
    return seed / 2_147_483_647
  }
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < particleColumns; column += 1) {
      const index = row * particleColumns + column
      spots.set([(column + 0.5) / particleColumns, (row + 0.5) / rows], index * 2)
      drifts.set([(random() - 0.5) * 0.5, random() * 0.25, 0.15 + random() * 0.45], index * 3)
    }
  }
  const geometry = new BufferGeometry()
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(count * 3), 3))
  geometry.setAttribute("spot", new BufferAttribute(spots, 2))
  geometry.setAttribute("drift", new BufferAttribute(drifts, 3))
  const particles = new Points(
    geometry,
    new ShaderMaterial({
      uniforms,
      vertexShader: particleVertex,
      fragmentShader: particleFragment,
      transparent: true,
      depthWrite: false,
    }),
  )
  particles.frustumCulled = false
  particles.renderOrder = 2

  return {
    plane,
    particles,
    uniforms,
    /** Puts the photo at `center`, `width` × `height` in world units, its particles too, at `pixels` per world unit. */
    place(center: Vector3, width: number, height: number, pixels: number) {
      plane.position.copy(center)
      particles.position.copy(center)
      plane.scale.set(width, height, 1)
      uniforms.size.value = [width, height]
      uniforms.pointSize.value = (width / particleColumns) * pixels * 1.2
    },
    /** How far the photo has burned (0 to 1), how opaque it is, and whether its particles show. */
    set({ progress, opacity, particles: shown }: { progress?: number; opacity?: number; particles?: boolean }) {
      if (progress !== undefined) uniforms.progress.value = progress
      if (opacity !== undefined) uniforms.opacity.value = opacity
      if (shown !== undefined) particles.visible = shown
    },
    hide() {
      plane.visible = false
      particles.visible = false
    },
    dispose() {
      plane.geometry.dispose()
      ;(plane.material as ShaderMaterial).dispose()
      geometry.dispose()
      ;(particles.material as ShaderMaterial).dispose()
    },
  }
}

type Dissolve = ReturnType<typeof createDissolve>

export { createDissolve }
export type { Dissolve }

import { useFrame, useThree } from "@react-three/fiber"
import { use, useEffect, useMemo, useRef, useState } from "react"
import { Color, SRGBColorSpace, TextureLoader, type PerspectiveCamera, type Texture } from "three"

import { createDissolve } from "@/components/ui/model-scan-dissolve"
import { containSize, viewSizeAt } from "@/components/ui/model-viewer-math"
import type { ModelViewerHandle } from "@/components/ui/model-viewer-primitive"
import { ModelViewerSceneContext } from "@/components/ui/model-viewer-rig"

// Seconds: the photo burns away while the camera turns, or crossfades under reduced motion.
const flight = 2.6
const crossfade = 0.7

const smoothstep = (from: number, to: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)))
  return t * t * (3 - 2 * t)
}

/** A theme colour as three.js reads it: the canvas paints the token, whatever colour space it's written in. */
function tokenColor(element: Element, name: string) {
  const value = getComputedStyle(element).getPropertyValue(name).trim()
  const canvas = element.ownerDocument.createElement("canvas")
  canvas.width = 1
  canvas.height = 1
  const context = canvas.getContext("2d")
  if (!value || !context) return new Color(0x3b82f6)
  context.fillStyle = value
  context.fillRect(0, 0, 1, 1)
  const [r = 0, g = 0, b = 0] = context.getImageData(0, 0, 1, 1).data
  return new Color().setRGB(r / 255, g / 255, b / 255, SRGBColorSpace)
}

// The chosen view becomes the three-quarter one, and the camera turns there even if it was chosen already.
function turn(handle: ModelViewerHandle) {
  handle.api.setView("three-quarter")
  handle.api.aim("three-quarter")
}

type IntroOptions = {
  src: string
  /** The photo's width over its height. */
  ratio: number
  /** The 3D photo matches the 2D one: the 2D layer can go. */
  onHandOff: () => void
  /** The model has taken the photo's place. */
  onDone: () => void
}

/**
 * The photo on a plane where the front camera sees it exactly as the 2D photo was drawn, then, once the model has
 * loaded, the camera turns to the three-quarter view while the photo burns into particles and the model fades in
 * where it stood. Under reduced motion the photo crossfades into the model and the camera jumps after.
 */
function useModelScanIntro({ src, ratio, onHandOff, onDone }: IntroOptions) {
  const scene = use(ModelViewerSceneContext)
  const camera = useThree((state) => state.camera) as PerspectiveCamera
  const canvas = useThree((state) => state.gl.domElement)
  const invalidate = useThree((state) => state.invalidate)
  // `texture: null` once the photo failed to load.
  const [texture, setTexture] = useState<{ src: string; texture: Texture | null } | null>(null)

  useEffect(() => {
    let current: Texture | undefined
    let cancelled = false
    new TextureLoader().loadAsync(src).then(
      (loaded) => {
        loaded.colorSpace = SRGBColorSpace
        if (cancelled) {
          loaded.dispose()
          return
        }
        current = loaded
        setTexture({ src, texture: loaded })
      },
      () => {
        // Without the photo in 3D the model still appears, and the 2D photo hands over to it.
        if (!cancelled) setTexture({ src, texture: null })
      },
    )
    return () => {
      cancelled = true
      current?.dispose()
    }
  }, [src])

  const loaded = texture?.src === src ? texture : null
  const map = loaded?.texture ?? null
  const dissolve = useMemo(
    () => (map ? createDissolve(map, ratio, tokenColor(canvas, "--info")) : null),
    [map, ratio, canvas],
  )
  useEffect(() => () => dissolve?.dispose(), [dissolve])
  const rig = scene?.rig
  useEffect(() => () => rig?.setOpacity(1), [rig])

  // useFrame calls the newest render's callback, so these are the newest props.
  const handOff = () => onHandOff()
  const done = () => onDone()
  const clock = useRef({ frames: 0, start: -1, aimed: false, finished: false })

  useFrame((state) => {
    if (!scene || !rig || !loaded || clock.current.finished) return
    const { handle, framing } = scene
    const reduced = handle.get().reducedMotion
    const intro = clock.current
    if (!dissolve) {
      intro.finished = true
      handOff()
      turn(handle)
      done()
      return
    }
    const framed = rig.frame(framing, camera)
    const view = viewSizeAt(framed.distance, camera.fov, camera.aspect)
    const photo = containSize(ratio, view)
    const pixels = state.gl.domElement.height / (2 * Math.tan(((camera.fov / 2) * Math.PI) / 180))
    dissolve.place(framed.center, photo.width, photo.height, pixels)

    intro.frames += 1
    // The rig turns the camera on the frame after a call: the first frame jumps to the front, the second draws the
    // photo there, and the third hands over, once that one is on screen.
    if (intro.frames === 1) {
      dissolve.set({ particles: !reduced })
      rig.setOpacity(0)
      handle.api.aim("front", "jump")
    }
    if (intro.frames === 3) {
      handOff()
      intro.start = state.clock.elapsedTime
    }
    state.invalidate()
    if (intro.start < 0) return

    const duration = reduced ? crossfade : flight
    const u = (state.clock.elapsedTime - intro.start) / duration
    if (reduced) {
      dissolve.set({ opacity: 1 - smoothstep(0, 1, u) })
      rig.setOpacity(smoothstep(0, 1, u))
    } else {
      if (!intro.aimed && u > 0.08) {
        intro.aimed = true
        turn(handle)
      }
      dissolve.set({ progress: smoothstep(0.08, 0.8, u) })
      rig.setOpacity(smoothstep(0.3, 0.85, u))
    }
    if (u < 1) return
    intro.finished = true
    dissolve.hide()
    rig.setOpacity(1)
    if (reduced) turn(handle)
    invalidate()
    done()
  })

  return dissolve
}

export { useModelScanIntro }

"use client"

import { useModelScanIntro } from "@/components/ui/use-model-scan-intro"

type ModelScanIntroProps = {
  src: string
  ratio: number
  onHandOff: () => void
  onDone: () => void
}

/** ModelScan's photo-to-model transition, inside the viewer's canvas; loaded with the scene, only by ModelScan. */
function ModelScanIntro(props: ModelScanIntroProps) {
  const dissolve = useModelScanIntro(props)
  if (!dissolve) return null
  return (
    <>
      <primitive object={dissolve.plane} />
      <primitive object={dissolve.particles} />
    </>
  )
}

export { ModelScanIntro }
export type { ModelScanIntroProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createParts, usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { lazy, useMemo, useState, type CSSProperties, type ReactNode } from "react"
import { CircleAlertIcon, RotateCcwIcon, XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { modelScanLabels, type ModelScanLabels } from "@/components/ui/model-scan-labels"
import {
  modelScan,
  type ModelScanActionReason,
  type ModelScanAnnouncements,
  type ModelScanStage,
} from "@/components/ui/model-scan-primitive"
import {
  pointGroups,
  type ModelScanDrawnGroup,
  type ModelScanPoint,
  type ModelScanPointGroup,
  type ModelScanPointList,
  type ModelScanPoints,
} from "@/components/ui/model-scan-points"
import {
  ModelViewer,
  type ModelViewerExpressions,
  type ModelViewerProps,
  type ModelViewerSource,
  type ModelViewerWeights,
} from "@/components/ui/model-viewer"
import { Progress, ProgressLabel, ProgressTrack, ProgressValue } from "@/components/ui/progress"
import { cn, cnState } from "@/lib/utils"

const {
  Photo: ModelScanPhoto,
  Effect: ModelScanEffect,
  Points: ModelScanPointLayer,
} = createParts(modelScan, { photo: "div", effect: "div", points: "div" })

// Loaded inside the viewer's canvas, after the viewer's own scene: only ModelScan pays for the photo transition.
const ModelScanIntro = lazy(() =>
  import("@/components/ui/model-scan-intro").then((module) => ({ default: module.ModelScanIntro })),
)

type ModelScanEventDetails = ChangeDetails<ModelScanActionReason>

/**
 * A model as an engine sends it: the GLB (bytes or a URL) and its target names. A new one (a refined character) fades
 * in over the last, or replaces it at once when it looks the same, keeping its weights.
 */
type ModelScanModel = { glb: ArrayBuffer | string; targetNames?: readonly string[] }

const isScanModel = (model: ModelViewerSource | ModelScanModel): model is ModelScanModel =>
  typeof model === "object" && "glb" in model

type ModelScanViewerProps = Omit<
  ModelViewerProps,
  | "model"
  | "alt"
  | "weights"
  | "targetNames"
  | "expressions"
  | "poster"
  | "controls"
  | "load"
  | "overlay"
  | "sceneChildren"
  | "aspectRatio"
>

type ModelScanProps = Omit<PartProps<"div">, "children"> & {
  /** The photo. */
  src: string
  /** Describes the photo, and names the scan. */
  alt: string
  /** The photo's size in pixels; its ratio sizes the stage before it loads. */
  width: number
  height: number
  stage: ModelScanStage
  /**
   * Points the engine found, as fractions of the photo, lighting up while detecting: one list (interleaved x, y in a
   * `Float32Array`, or `{ x, y }` objects), or groups of them, `{ source, points, aspect? }`, each lighting up on its
   * own, in the order the sources arrived.
   */
  points?: ModelScanPoints
  /** The base model (a GLB with morph targets), from the building stage on. */
  model?: ModelViewerSource | ModelScanModel
  /** Morph target weights from the engine, eased as they stream in: aligned with the target names, or by name. */
  weights?: ModelViewerWeights
  /** The order aligned `weights` follow, when `model` doesn't carry it; the GLB's `extras.targetNames` by default. */
  targetNames?: readonly string[]
  /** Expression weights by ARKit name, like a smile at the end. */
  expressions?: ModelViewerExpressions
  /** From 0 to 1 within the stage; leave it out while the engine can't tell. */
  progress?: number
  /** What the engine is doing now, as the progress bar's label; the stage's label by default. */
  statusText?: string
  /** What went wrong, shown and read at once in the error stage. */
  error?: string
  /** Shows Cancel before the model is ready; agents call `cancel`. */
  onCancel?: (details: ModelScanEventDetails) => void
  /** Shows Retry after an error; agents call `retry`. */
  onRetry?: (details: ModelScanEventDetails) => void
  /** Describes the model once it shows; `labels.model` by default. */
  modelAlt?: string
  /** The clip to play when ready, like a wave; the model's first clip by default. */
  idleClip?: string
  /** The stage's width over its height; the photo's by default. */
  aspectRatio?: number
  /** More ModelViewer props for the model: framing, material, summary, labels… */
  viewer?: ModelScanViewerProps
  /** More controls beside Cancel and Retry. */
  actions?: ReactNode
  labels?: Partial<ModelScanLabels>
}

/* oxlint-disable shadcn/no-arbitrary-values -- the photo's drawn box and the scan effect follow the ratio, progress and container variables */
// The photo's drawn box inside the stage, as ImageScan places its regions: points land on the pixels they name.
const layerClassName =
  "pointer-events-none absolute top-1/2 left-1/2 h-[min(100cqh,calc(100cqw/var(--model-scan-ratio)))] w-[min(100cqw,calc(100cqh*var(--model-scan-ratio)))] -translate-x-1/2 -translate-y-1/2"
// A size container (Tailwind's @container is inline-size only), so the photo's box sizes from it.
const photoClassName = "pointer-events-none absolute inset-0 [container-type:size] data-handed-off:invisible"
const effectClassNames = {
  root: "group/effect absolute inset-0 overflow-hidden [--model-scan-accent:var(--info)]",
  veil: "absolute inset-0 origin-bottom bg-overlay opacity-40 transition-transform duration-panel ease-standard group-data-determinate/effect:scale-y-[calc(1-var(--model-scan-progress,0))]",
  line: "absolute inset-x-0 bottom-full hidden h-full translate-y-[calc(var(--model-scan-progress,0)*100%)] border-b-2 border-(--model-scan-accent) bg-linear-to-b from-transparent to-(--model-scan-accent)/25 transition-transform duration-panel ease-standard group-data-determinate/effect:block",
  bracket:
    "absolute size-6 border-(--model-scan-accent) drop-shadow-[0_0_1px_var(--background)] motion-safe:animate-pulse",
}
// Each point grows in after the one before it in its group, at most 0.4 s behind the first, so a group (the face,
// the body) lights up on its own when it arrives. Groups take the info, violet and success colours in turn.
const pointClassName =
  "absolute size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-(--model-scan-point) shadow-[0_0_0_1.5px_var(--background),0_0_6px_var(--model-scan-point)] transition-[scale,opacity] delay-[min(calc(var(--model-scan-point-index)*4ms),400ms)] duration-micro ease-standard starting:scale-0 starting:opacity-0"
const groupClassName =
  "absolute inset-0 [--model-scan-point:var(--info)] data-[order=1]:[--model-scan-point:var(--violet)] data-[order=2]:[--model-scan-point:var(--success)]"
/* oxlint-enable shadcn/no-arbitrary-values */

const working: readonly ModelScanStage[] = ["detecting", "building", "refining"]
const threeD: readonly ModelScanStage[] = ["building", "refining", "ready"]

/**
 * A photo turning into a 3D character, driven by an engine's events through props: points light up over the photo
 * (`detecting`), the photo burns into particles while the camera turns and the base model appears where it stood
 * (`building`), streamed weights reshape it (`refining`), and it plays its idle clip and turns freely (`ready`).
 * Reduced motion crossfades the photo into the model instead. Every stage is announced, errors at once.
 */
function ModelScan({
  src,
  alt,
  width,
  height,
  stage,
  points,
  model,
  weights,
  targetNames,
  expressions,
  progress,
  statusText,
  error,
  onCancel,
  onRetry,
  modelAlt,
  idleClip,
  aspectRatio,
  viewer: viewerProps,
  actions,
  labels: ownLabels,
  className,
  ...props
}: ModelScanProps) {
  const labels = { ...modelScanLabels, ...ownLabels, stage: { ...modelScanLabels.stage, ...ownLabels?.stage } }
  const ratio = width / height
  const groups = useMemo(() => pointGroups(points, ratio), [points, ratio])
  const glb = model && isScanModel(model) ? model.glb : model
  const modelNames = model && isScanModel(model) ? model.targetNames : undefined
  const announcements: ModelScanAnnouncements = {
    stage: (next) =>
      next === "photo" || next === "error" ? undefined : next === stage && statusText ? statusText : labels.stage[next],
    progress: labels.progress,
    error: error ?? labels.error,
  }
  const [playing, setPlaying] = useState<boolean | null>(null)
  const [handedOff, setHandedOff] = useState(false)
  const [introDone, setIntroDone] = useState(false)
  // A new run (back to the photo, or detecting again) starts over in 2D.
  if ((stage === "photo" || stage === "detecting") && (handedOff || introDone)) {
    setHandedOff(false)
    setIntroDone(false)
  }
  const scan = usePrimitive(modelScan, {
    stage,
    progress,
    onCancel: onCancel && ((_value, details) => onCancel(details)),
    onRetry: onRetry && ((_value, details) => onRetry(details)),
    ratio,
    introDone,
    announcements,
  })
  const intro = threeD.includes(stage) || (stage === "error" && handedOff)
  const shownModel = handedOff && stage !== "photo" && stage !== "detecting"

  const overlay = (
    <ModelScanPhoto handedOff={handedOff} className={photoClassName}>
      <img
        src={src}
        alt=""
        width={width}
        height={height}
        draggable={false}
        className="absolute inset-0 size-full object-contain"
      />
      <div className={layerClassName}>
        <ModelScanEffect className={effectClassNames.root}>
          <span className={effectClassNames.veil} />
          <span className={effectClassNames.line} />
          <span className={cn(effectClassNames.bracket, "top-group left-group rounded-tl-sm border-t-2 border-l-2")} />
          <span className={cn(effectClassNames.bracket, "top-group right-group rounded-tr-sm border-t-2 border-r-2")} />
          <span
            className={cn(effectClassNames.bracket, "right-group bottom-group rounded-br-sm border-r-2 border-b-2")}
          />
          <span
            className={cn(effectClassNames.bracket, "bottom-group left-group rounded-bl-sm border-b-2 border-l-2")}
          />
        </ModelScanEffect>
        <ModelScanPointLayer handedOff={handedOff} className="absolute inset-0">
          {groups.map((group, order) => (
            <ModelScanPointGroupLayer key={group.source} group={group} order={order} />
          ))}
        </ModelScanPointLayer>
      </div>
    </ModelScanPhoto>
  )

  const content = (
    <>
      <ModelViewer
        {...viewerProps}
        model={glb}
        targetNames={targetNames ?? modelNames}
        expressions={expressions}
        aria-label={modelAlt ?? labels.model}
        alt={shownModel ? (modelAlt ?? labels.model) : alt}
        poster={src}
        aspectRatio={aspectRatio ?? ratio}
        weights={weights}
        load={stage !== "photo"}
        controls={stage === "ready"}
        playing={stage === "ready" && introDone ? playing : false}
        onPlayingChange={(next, details) => {
          viewerProps?.onPlayingChange?.(next, details)
          if (!details.canceled) setPlaying(next)
        }}
        defaultClip={idleClip ?? viewerProps?.defaultClip}
        overlay={overlay}
        sceneChildren={
          intro ? (
            <ModelScanIntro
              src={src}
              ratio={ratio}
              onHandOff={() => setHandedOff(true)}
              onDone={() => setIntroDone(true)}
            />
          ) : null
        }
      />
      <ModelScanStatus
        stage={stage}
        progress={progress}
        statusText={statusText}
        error={error}
        labels={labels}
        actions={actions}
        cancel={onCancel && stage !== "ready" && stage !== "error" ? (event) => scan.api.cancel(event) : undefined}
        retry={onRetry && stage === "error" ? (event) => scan.api.retry(event) : undefined}
      />
    </>
  )

  return usePart(
    scan,
    "root",
    {},
    {
      "aria-label": alt,
      ...props,
      className: cnState("flex w-full min-w-0 flex-col gap-items", className),
      children: content,
    },
    "div",
  )
}

/** One group's points, drawn as dots at their fractions of the photo; decorative, inside the hidden points layer. */
function ModelScanPointGroupLayer({ group, order }: { group: ModelScanDrawnGroup; order: number }) {
  const dots: ReactNode[] = []
  for (let i = 0; i + 1 < group.coords.length; i += 2) {
    const index = i / 2
    // Points of a group only arrive, never move or reorder: their place in the list is their identity.
    dots.push(
      <span
        key={index}
        className={pointClassName}
        style={
          {
            left: `${String(((group.coords[i] ?? 0) * 100).toFixed(2))}%`,
            top: `${String(((group.coords[i + 1] ?? 0) * 100).toFixed(2))}%`,
            "--model-scan-point-index": String(index),
          } as CSSProperties
        }
      />,
    )
  }
  return (
    <span data-source={group.source} data-order={order % 3} className={groupClassName}>
      {dots}
    </span>
  )
}

type ModelScanStatusProps = {
  stage: ModelScanStage
  progress?: number
  statusText?: string
  error?: string
  labels: ModelScanLabels
  actions?: ReactNode
  cancel?: (event: Event) => void
  retry?: (event: Event) => void
}

/** Under the stage: the progress and Cancel while working, the error and Retry after a failure. */
function ModelScanStatus({ stage, progress, statusText, error, labels, actions, cancel, retry }: ModelScanStatusProps) {
  if (stage === "error") {
    return (
      <div className="flex flex-wrap items-center gap-items">
        <p className="flex min-w-0 flex-1 basis-48 items-center gap-inline text-body-sm text-destructive-soft-foreground">
          <CircleAlertIcon aria-hidden className="size-4 shrink-0" />
          <span className="min-w-0">{error ?? labels.error}</span>
        </p>
        {retry ? (
          <Button variant="outline" size="sm" onClick={(event) => retry(event.nativeEvent)}>
            <RotateCcwIcon />
            {labels.retry}
          </Button>
        ) : null}
        {actions}
      </div>
    )
  }
  if (!working.includes(stage)) {
    if (!cancel && !actions) return null
    return (
      <div className="flex flex-wrap items-center justify-end gap-items">
        {cancel ? (
          <Button variant="outline" size="sm" onClick={(event) => cancel(event.nativeEvent)}>
            <XIcon />
            {labels.cancel}
          </Button>
        ) : null}
        {actions}
      </div>
    )
  }
  const label = statusText ?? labels.stage[stage as Exclude<ModelScanStage, "photo" | "error">]
  return (
    <div className="flex items-end gap-items">
      <Progress value={progress === undefined ? null : Math.round(progress * 1000) / 10} className="min-w-0 flex-1">
        <ProgressLabel className="min-w-0 truncate">{label}</ProgressLabel>
        <ProgressValue />
        <ProgressTrack />
      </Progress>
      {cancel ? (
        <Button variant="outline" size="sm" onClick={(event) => cancel(event.nativeEvent)}>
          <XIcon />
          {labels.cancel}
        </Button>
      ) : null}
      {actions}
    </div>
  )
}

export { ModelScan, modelScanLabels }
export type {
  ModelScanEventDetails,
  ModelScanLabels,
  ModelScanModel,
  ModelScanPoint,
  ModelScanPointGroup,
  ModelScanPointList,
  ModelScanPoints,
  ModelScanProps,
  ModelScanStage,
}
